            "إظهار أن اختيار المواقع قائم على دراسة",
            "خريطة مبسطة حول نقطة المشروع وبجوارها 3 أسئلة: مين هيستخدمه؟ إيه اللي حواليه؟ هل قيمته هتكمل؟",
            "بكل فخر بنقول ان مواقع مشاريعنا الأكثر تميز ف بني سويف",
            "اختيار الأرض مش أول خطوة في البناء… ده أول اختبار للمشروع.\n\nقبل أي تصميم أو إعلان، بنبص على المكان: احتياج الناس، طبيعة المنطقة، وإمكانية إن المشروع يفضل له قيمة مع الوقت.\n\nلأن المشروع الصح مش بس شكله حلو؛ لازم يكون موجود في مكان له سبب.",
