            "لما نفهم احتياجك، نقدر نوجهك بشكل أوضح.",
            "مش كل وحدة تناسب كل شخص، ومش كل قرار شراء بيتاخد بنفس الطريقة.\n\nعشان كده بنبدأ بالسؤال قبل العرض: هتشتري للسكن ولا للاستثمار؟ محتاج مساحة قد إيه؟ وميزانيتك في حدود كام؟\n\nلما نفهم احتياجك، نقدر نوجهك بشكل أصدق وأوضح.",
