            "بنقدم جميع الإصلاحات والصيانات اللازمة للعربيات الألماني والفرنسي، بالإضافة لخدمات الميكانيكا والعفشة وكشف الكمبيوتر.كل خطوة بتبدأ بفهم الحالة، عشان الخدمة تكون مناسبة للعربية فعلًا.إيه أكتر حاجة بتخليكي تروحي تكشفي على عربيتك؟ صوت؟ لمبة؟ اهتزاز؟",
