            "صورة Close-up لوجه طبيعي من الأمام. الصورة مقسومة بخط رأسي رفيع جدًا. ناحية يظهر عليها فلتر واضح ومبالغ فيه: تنعيم زائد واختفاء تفاصيل البشرة. الناحية الثانية طبيعية تمامًا لكن بإضاءة صحية وتفاصيل بشرة حقيقية. في المنتصف Overlay بسيط يربط الناحيتين، وفي الجزء السفلي اسم الخدمة بحجم واضح: «عرض الديرما بن». التصميم كله نظيف، ومافيش صورة جهاز أو أدوات طبية كتير.",
            "بشرتك مش محتاجة فلتر… محتاجة تجديد.",
