            "لقطة Close-up لبشرة طبيعية كخلفية أساسية. فوق الصورة 3 طبقات شفافة رفيعة جدًا، كل طبقة تمثل Layer من التراكمات، وتكون الطبقات بتتحرك بصريًا من أعلى لأسفل أو تنسحب ناحية الخارج. في كل طبقة كلمة صغيرة جدًا مثل: «بهتان / ملمس / تصبغات». في المنتصف الجملة الرئيسية، وأسفلها Badge واضح «عرض التقشير». وبجوار اسم العرض Note صغيرة: «حسب احتياج بشرتك».",
