            "التصميم يبدأ بصورة بشرة طبيعية قبل التنظيف كخلفية، لكن من غير تقسيمة Before/After التقليدية. نستخدم عنصر بصري يشبه دائرة Focus أو عدسة مكبرة على جزء من البشرة، والجزء داخلها يظهر أنظف وأنقى من باقي الصورة. فوق الصورة جملة التصميم. وفي أسفل التصميم شريط بسيط يحمل اسم «عرض تنظيف البشرة». كده الفكرة كلها مبنية على «تنضيف البداية» من غير ما التصميم يبقى Before/After مستهلك.",
