            "صورة حقيقية للعمال أو المعدات في الموقع، مع لوجو صغير وهادئ. بدون مونتاج أو تفاصيل كثيرة حتى تفضل الصورة هي الأساس.",
            "من موقع قصر الأوركيد",
            "كل مرحلة ليها تفاصيلها، وقصر الأوركيد بدأ ياخد أول خطواته على أرض الواقع. وهنفضل نشاركك خطوات المشروع أول بأول، من بداية الحفر ومع كل مرحلة جديدة في التنفيذ، عشان تقدر تتابع تطور المشروع وتشوف تفاصيله وهي بتظهر خطوة بخطوة على أرض الواقع.",
