            "صورة عقد وقلم على مكتب هادي، مع ترك مساحة واضحة للجملة الرئيسية وبدون تفاصيل بصرية كثيرة.",
            "قبل الإمضا\n اسأل عن كل بند",
            "قبل الإمضا، اقرأ العقد براحتك واسأل عن كل بند. السعر، المقدم، الأقساط، الرسوم، وموعد التسليم... ما تستعجلش في خطوة التعاقد قبل ما تكون كل التفاصيل واضحة بالنسبة لك. كل بند تفهمه وتسأل عنه من البداية، بيخلي قرارك أهدى وأوضح ويجنبك أي تفاصيل غير واضحة بعد كده.",
