            "في قصر الأوركيد، مساحة الشقة 185 متر. لكن المهم في المساحة مش الرقم بس، المهم كمان توزيعها وإزاي كل ركن فيها يخدم استخدامك. لأن المساحة العملية هي اللي تقدر تستفيد من كل جزء فيها، وتكون مناسبة لطريقة يومك واحتياجاتك، مش مجرد رقم مكتوب على الورق.",
