            "خط زمني بسيط جدًا يوضح: الأرض → الأساس → المبنى، مع الحفاظ على تصميم هادئ وواضح.",
            "الأرض... الأساس... وبعدها يبدأ شكل المشروع",
            "قصر الأوركيد بدأ من الأرض، والحفر هو أول مرحلة في طريق التنفيذ. ومع كل مرحلة جديدة، المشروع بيبدأ ياخد شكل أوضح على أرض الواقع. كل خطوة ليها وقتها وترتيبها، وهنفضل نشارككم التفاصيل مع تطور التنفيذ لحد ما يبدأ شكل المشروع يبان قدامكم بشكل أوضح.",
