            "ربط رحال ببداية اليوم والصحيان بدري بطريقة كوميدية.",
            "Comic 3 كادرات: نوم عميق → منبهات كتير → الطالب صاحي قدام القهوة. تفاصيل قليلة وجملة واحدة واضحة.",
