            "Flat lay لشنطة مفتوحة، كل عنصر عليه اسم صغير، وكيس التلقيمة عليه علامة أساسي.",
            "أهم حاجة في الشنطة — بن رحال",
            "الكتب عشان الدراسة، الشاحن عشان الموبايل، وكيس التلقيمة عشان اليوم الطويل اللي بيبدأ بمحاضرة وينتهي وإنت مش عارف خلص إمتى 😅 إيه أكتر حاجة أساسية في شنطتك؟",
