            "استهداف طلاب المدارس بموقف يومي مألوف وقابل للمشاركة.",
            "Comic في ساحة مدرسة؛ كل الشخصيات نعسانة وشخصية واحدة فقط واقفة بثقة ومعها فنجان رحال.",
            "صاحي بالعافية — إسبريسو",
            "طابور الصباح محتاج حضور وانضباط… ومحتاج كمان سبب يخليك واقف على رجلك بدل ما تكمل نومك وإنت واقف 😂 كنت بتقف في الطابور ولا بتحاول تختفي ورا أصحابك؟",
