            "صورتان لنفس الشخصية: متحمس بشنطة جديدة → مرهق ومعه رحال.",
            "الحماس خلص — رحال غامق",
            "أول يوم بيبدأ بصور للشنطة والكتب وكلام عن الاجتهاد… وبعد أول محاضرتين بنكتشف إننا محتاجين قهوة وخطة نجاة لباقي الترم 😂 حماسك للدراسة بيستمر لحد إمتى؟",
