            "تحويل زيارة رحال إلى جزء من جدول الطالب اليومي.",
            "تصميم يشبه تطبيق مواعيد، وبين المحاضرات خانة مميزة: استراحة قهوة.",
            "فين وقت القهوة؟ — رحال وسط",
            "الجدول منظم، المحاضرات متسجلة، والتكليفات مكتوبة… فاضل بس تحط وقت لنفسك. لأن الطالب اللي بيجري طول اليوم من غير استراحة بيخلص اليوم وهو محتاج إجازة 😅 قهوتك قبل المحاضرة ولا بينها؟",
