            "تصميم يشبه ماتش أو بطولة بين أربع مناطق، وكل منطقة تظهر كشخصية كرتونية ماسكة وجبة من تميم.",
            "خلق حماس عام للحملة وتعريف الجمهور بالمنافسة والخصومات",
            "خلفية ملعب، وفي المنتصف كأس مكتوب عليه عزومة تميم ، وأسماء المناطق الأربعة في شكل فرق متنافسة، مع عداد طلبات فارغ قابل للتحديث يوميًا.",
            "منطقتك هتكسب العزومة؟",
            "النزلة؟ العجمين؟ أبو كساه؟ النصارية؟ أبو جنشو؟ المنافسة بدأت  اطلب من تميم، اعمل لايك وكومنت باسم منطقتك، وخلي منطقتك تكسب توصيل مجاني بكرة، وكل المناطق ليها خصم %50 على التوصيل حسب الشروط!اكتب اسم منطقتك واعمل منشن لحد منها.",
