            "يا أهل النزلة وّرّوا تميم مين الأبطال!",
            "النزلة دخلت المنافسة ومش ناوية تسيب الكأس لحد  اطلب من تميم، اكتب «النزلة» في الكومنت، وخلي التوصيل المجاني يروح لأهل منطقتك بكرة.اكتب «النزلة» في الكومنت.",
