            "رفع عدد الطلبات من العجمين وزيادة التعليقات والمنشنات",
            "شخصية كرتونية هادئة جدًا ماسكة ساندوتش تميم، وفوقها جملة ساكتين بس بنطلب ، وتظهر المناطق الأخرى في الخلفية وهي قلقة من ارتفاع العداد.",
            "العجمين ساكتة بس بتكسب!",
